"use client";

import { useEffect, useState } from "react";
import { usePagination } from "./use-pagination";
import styles from "./pagination.module.scss";

// Mobilde pencereyi biraz daralt (±2 -> 5 sayı), masaüstünde ±3 (7 sayı).
function useIsMobile() {
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 575.98px)");
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);
  return isMobile;
}

export default function Pagination({
  onPageChange,
  totalCount,
  currentPage,
  pageSize,
}: {
  onPageChange: any;
  totalCount: any;
  currentPage: any;
  pageSize: any;
}) {
  const isMobile = useIsMobile();
  const paginationRange = usePagination({
    currentPage,
    totalCount,
    pageSize,
    siblingCount: isMobile ? 2 : 3,
  });

  if (currentPage === 0 || paginationRange.length < 2) {
    return null;
  }

  const totalPageCount = Math.ceil(totalCount / pageSize);
  const isFirst = currentPage <= 1;
  const isLast = currentPage >= totalPageCount;

  const onNext = () => onPageChange(currentPage + 1);
  const onPrevious = () => onPageChange(currentPage - 1);

  return (
    <nav aria-label="Page navigation" className={styles.nav}>
      <ul className={styles.list}>
        {!isFirst && (
          <li className={styles.item}>
            <button
              type="button"
              className={`${styles.link} ${styles.arrow}`}
              onClick={onPrevious}
              aria-label="Previous page"
            >
              <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <path
                  d="M15 6l-6 6 6 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </li>
        )}

        {paginationRange.map((pageNumber: number) => {
          const isActive = pageNumber === currentPage;
          return (
            <li
              className={`${styles.item} ${isActive ? styles.active : ""}`}
              key={pageNumber}
            >
              <button
                type="button"
                className={styles.link}
                onClick={() => onPageChange(pageNumber)}
                aria-current={isActive ? "page" : undefined}
              >
                {pageNumber}
              </button>
            </li>
          );
        })}

        {!isLast && (
          <li className={styles.item}>
            <button
              type="button"
              className={`${styles.link} ${styles.arrow}`}
              onClick={onNext}
              aria-label="Next page"
            >
              <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <path
                  d="M9 6l6 6-6 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </li>
        )}
      </ul>
    </nav>
  );
}
