import { useMemo } from "react";

// Minimal kayan pencere: ilk/son sayfa ve "..." yok. Aktif sayfanın etrafında
// sabit genişlikte bir pencere gösterilir; kenarlara gelince pencere sabitlenir.
// Örn. siblingCount=2, 36 sayfa: sayfa 5 -> [3,4,5,6,7], sayfa 1 -> [1..5],
// son sayfa -> [32..36].
export const usePagination = ({
  totalCount,
  pageSize,
  currentPage,
  siblingCount = 2,
}: {
  totalCount: any;
  pageSize: any;
  currentPage: any;
  siblingCount?: number;
}) => {
  return useMemo(() => {
    const totalPageCount = Math.ceil(totalCount / pageSize);
    if (!totalPageCount || totalPageCount <= 1) return [];

    const windowSize = siblingCount * 2 + 1;
    if (totalPageCount <= windowSize) {
      return Array.from({ length: totalPageCount }, (_, i) => i + 1);
    }

    let start = currentPage - siblingCount;
    let end = currentPage + siblingCount;

    if (start < 1) {
      start = 1;
      end = windowSize;
    }
    if (end > totalPageCount) {
      end = totalPageCount;
      start = totalPageCount - windowSize + 1;
    }

    return Array.from({ length: end - start + 1 }, (_, i) => start + i);
  }, [totalCount, pageSize, currentPage, siblingCount]);
};
